import secrets
from typing import Dict, List


class _User:
    def __init__(self, email: str, password: str, is_admin: bool = False) -> None:
        self.email = email
        self.password = password
        self.is_admin = is_admin


class AccountService:
    def __init__(self) -> None:
        # Maps normalized (lowercase) email to _User instance
        self._users: Dict[str, _User] = {}
        # Maps reset token to normalized (lowercase) target email
        self._reset_tokens: Dict[str, str] = {}

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long.")

        normalized_email = email.lower()
        if normalized_email in self._users:
            raise ValueError(f"An account for '{email}' already exists.")

        self._users[normalized_email] = _User(
            email=normalized_email,
            password=password,
            is_admin=is_admin,
        )

    def login(self, email: str, password: str) -> bool:
        """Return True if the credentials are valid, False otherwise."""
        normalized_email = email.lower()
        user = self._users.get(normalized_email)
        if user is None:
            return False

        # Passwords are compared case-insensitively
        return user.password.lower() == password.lower()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        """`requester_email` asks for a password reset of `target_email`.
        Returns a one-time reset token."""
        requester = self._users.get(requester_email.lower())
        if requester is None or not requester.is_admin:
            raise PermissionError("Only administrators can request a password reset.")

        target_norm = target_email.lower()
        if target_norm not in self._users:
            raise ValueError(f"Target account '{target_email}' does not exist.")

        token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = target_norm
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        if token not in self._reset_tokens:
            raise ValueError("Invalid or already used reset token.")

        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long.")

        target_email = self._reset_tokens.pop(token)
        user = self._users.get(target_email)
        if user is not None:
            user.password = new_password

    def list_users(self) -> list[str]:
        """Return all registered email addresses, sorted alphabetically."""
        return sorted(self._users.keys())
```

